	c := mustCache(b, Config{Capacity: 100})
	c.Put("key", "value")
	for b.Loop() {
		c.Get("key")
	}
}

func BenchmarkPut(b *testing.B) {
	c := mustCache(b, Config{Capacity: 100})
	// Pre-fill to capacity so each Put causes eviction
	for i := range 100 {
		c.Put(fmt.Sprintf("k%d", i), "v")
	}
	i := 100
	for b.Loop() {
		c.Put(fmt.Sprintf("k%d", i), "v")
		i++
	}
}
